const response = $input.first().json;
const input = $('Webhook — Déclencher article').first().json;
const body = input.body || input;

let research;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  research = JSON.parse(text);
} catch (e) {
  research = { statistics: [], expert_quotes: [], key_points: [], faq: [], cultural_notes: [] };
}

return [{
  json: {
    subject: body.subject || '',
    main_keyword: body.main_keyword || body.Mot_Cle || '',
    secondary_keywords: body.secondary_keywords || body.Keywords_Secondaires || '',
    structure: body.structure || body.Structure || '',
    length: body.length || body.Longueur_Recommandee || 1500,
    local_angle: body.local_angle || body.Angle_Local || '',
    meta_description: body.meta_description || body.Meta_Description || '',
    research_data: research
  }
}];

const response = $input.first().json;
const inputData = $('Parse — Données recherche').first().json;

let article;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  article = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing article: ' + e.message);
}

// Generate Firestore-compatible BlogPost document
const now = new Date().toISOString();
const slug = (article.suggested_slug || article.title || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 80);

const blogPost = {
  title: article.title || inputData.subject,
  slug: slug,
  excerpt: article.excerpt || (article.meta_description || ''),
  content: article.content_html || '',
  coverImage: '',
  category: article.category || 'Marketing Digital',
  tags: article.tags || [],
  author: 'Max-Morrys',
  publishedAt: now,
  readTime: article.reading_time_minutes || Math.ceil((article.word_count || 1500) / 200),
  featured: false,
  status: 'draft',
  metaTitle: article.title || '',
  metaDescription: article.meta_description || '',
  focusKeyword: inputData.main_keyword || '',
  ogTitle: article.title || '',
  ogDescription: article.meta_description || '',
  ogImage: '',
  noIndex: false,
  createdAt: now
};

return [{
  json: {
    blogPost,
    featured_image_prompt: article.featured_image_prompt || '',
    internal_links: article.internal_links || [],
    faq: article.faq || [],
    word_count: article.word_count || 0
  }
}];
